"""Validation rules.

Each rule is a callable `rule(record, check, state) -> None` that raises
CheckFailure to reject the record. `state` is a per-run dict scoped to
one check instance, used by stateful rules such as `unique`.
"""

import datetime

from .errors import CheckFailure
from .utils.numbers import parse_decimal, parse_int
from .utils.text import is_blank


def rule_required(record, check, state):
    field = check["field"]
    if field not in record or is_blank(record[field]):
        raise CheckFailure("required field %r is missing or blank" % field, field=field)


def rule_type(record, check, state):
    """Check that the field parses as the declared type without changing it."""
    field = check["field"]
    if field not in record or is_blank(record[field]):
        return  # absence is `required`'s business, not ours
    expected = check.get("type", "str")
    value = record[field]
    try:
        if expected == "int":
            parse_int(value)
        elif expected == "decimal":
            parse_decimal(value)
        elif expected == "date":
            datetime.date.fromisoformat(str(value).strip())
        elif expected == "bool":
            if str(value).strip().lower() not in ("true", "false", "1", "0"):
                raise ValueError("not a boolean: %r" % value)
    except ValueError as exc:
        raise CheckFailure(str(exc), field=field)


def rule_range(record, check, state):
    field = check["field"]
    if field not in record or is_blank(record[field]):
        return
    try:
        value = parse_decimal(record[field])
    except ValueError as exc:
        raise CheckFailure(str(exc), field=field)
    low = check.get("min")
    high = check.get("max")
    if low is not None and value < parse_decimal(low):
        raise CheckFailure(
            "%s=%s is below the minimum %s" % (field, value, low), field=field
        )
    if high is not None and value > parse_decimal(high):
        raise CheckFailure(
            "%s=%s is above the maximum %s" % (field, value, high), field=field
        )


def rule_one_of(record, check, state):
    field = check["field"]
    if field not in record or is_blank(record[field]):
        return
    allowed = check.get("values", [])
    if record[field] not in allowed:
        raise CheckFailure(
            "%s=%r is not one of %s" % (field, record[field], ", ".join(allowed)),
            field=field,
        )


def rule_unique(record, check, state):
    """Reject records whose key fields repeat an earlier record's."""
    fields = check.get("fields") or [check["field"]]
    key = tuple(str(record.get(f, "")) for f in fields)
    seen = state.setdefault("seen", set())
    if key in seen:
        raise CheckFailure(
            "duplicate value for %s: %s" % ("+".join(fields), "/".join(key)),
            field=fields[0],
        )
    seen.add(key)


def rule_matches(record, check, state):
    """Substring / prefix check — deliberately not full regex to keep specs tame."""
    field = check["field"]
    if field not in record or is_blank(record[field]):
        return
    value = str(record[field])
    prefix = check.get("prefix")
    contains = check.get("contains")
    if prefix is not None and not value.startswith(prefix):
        raise CheckFailure(
            "%s=%r does not start with %r" % (field, value, prefix), field=field
        )
    if contains is not None and contains not in value:
        raise CheckFailure(
            "%s=%r does not contain %r" % (field, value, contains), field=field
        )


RULES = {
    "required": rule_required,
    "type": rule_type,
    "range": rule_range,
    "one_of": rule_one_of,
    "unique": rule_unique,
    "matches": rule_matches,
}

"""Transform operations.

Each op is a callable `op(record, spec_op) -> record` applied to every
surviving record in spec order. Ops return the (possibly new) record;
raising RecordError/ValueError routes the record to the rejects pile.
"""

import datetime
from decimal import Decimal

from .errors import RecordError
from .utils.numbers import format_money, parse_decimal, parse_int
from .utils.text import is_blank


def op_cast(record, op):
    """Cast a field to a real Python type: {"op":"cast","field":F,"to":T}."""
    field = op["field"]
    to = op.get("to", "str")
    if field not in record or is_blank(record[field]):
        return record
    value = record[field]
    try:
        if to == "int":
            record[field] = parse_int(value)
        elif to == "decimal":
            record[field] = parse_decimal(value)
        elif to == "date":
            record[field] = datetime.date.fromisoformat(str(value).strip())
        elif to == "bool":
            record[field] = str(value).strip().lower() in ("true", "1")
        elif to == "str":
            record[field] = str(value)
        else:
            raise RecordError("unknown cast target %r" % to, field=field)
    except ValueError as exc:
        raise RecordError("cast %s to %s failed: %s" % (field, to, exc), field=field)
    return record


def op_rename(record, op):
    """{"op":"rename","field":OLD,"to":NEW} — no-op if OLD is absent."""
    old, new = op["field"], op["to"]
    if old in record:
        record[new] = record.pop(old)
    return record


def op_default(record, op):
    """Fill a missing/blank field: {"op":"default","field":F,"value":V}."""
    field = op["field"]
    if field not in record or is_blank(record[field]):
        record[field] = op.get("value")
    return record


def op_drop(record, op):
    """Remove a field: {"op":"drop","field":F}."""
    record.pop(op["field"], None)
    return record


def op_derive(record, op):
    """Compute a new field from others.

    {"op":"derive","field":"total","formula":"multiply",
     "args":["quantity","unit_price"]}

    Formulas: multiply, add, subtract, money (re-format a decimal
    field to 2dp string), concat (join string fields with a space).
    """
    field = op["field"]
    formula = op.get("formula")
    args = op.get("args", [])
    values = []
    for name in args:
        if name not in record:
            raise RecordError(
                "derive %r needs field %r which is missing" % (field, name),
                field=name,
            )
        values.append(record[name])
    try:
        if formula == "multiply":
            result = _as_decimal(values[0])
            for v in values[1:]:
                result *= _as_decimal(v)
            record[field] = result
        elif formula == "add":
            result = _as_decimal(values[0])
            for v in values[1:]:
                result += _as_decimal(v)
            record[field] = result
        elif formula == "subtract":
            record[field] = _as_decimal(values[0]) - _as_decimal(values[1])
        elif formula == "money":
            record[field] = format_money(_as_decimal(values[0]))
        elif formula == "concat":
            record[field] = " ".join(str(v) for v in values)
        else:
            raise RecordError("unknown derive formula %r" % formula, field=field)
    except (ValueError, ArithmeticError) as exc:
        raise RecordError(
            "derive %r (%s) failed: %s" % (field, formula, exc), field=field
        )
    return record


def _as_decimal(value):
    if isinstance(value, Decimal):
        return value
    if isinstance(value, int):
        return Decimal(value)
    return parse_decimal(value)


OPS = {
    "cast": op_cast,
    "rename": op_rename,
    "default": op_default,
    "drop": op_drop,
    "derive": op_derive,
}

"""Numeric parsing and formatting helpers.

CSV sources deliver everything as strings, so the cast/derive ops lean
on these to turn "1,204.50" or " 7 " into usable numbers with clear
error messages when they cannot.
"""

from decimal import Decimal, InvalidOperation


def parse_int(value):
    """Parse an int, tolerating surrounding space and thousands commas.

    Raises ValueError with the offending text in the message.
    """
    if isinstance(value, bool):
        raise ValueError("cannot cast a boolean to int: %r" % value)
    if isinstance(value, int):
        return value
    text = str(value).strip().replace(",", "")
    try:
        return int(text)
    except ValueError:
        raise ValueError("not an integer: %r" % value)


def parse_decimal(value):
    """Parse a Decimal, tolerating surrounding space and a leading currency $."""
    if isinstance(value, Decimal):
        return value
    text = str(value).strip()
    if text.startswith("$"):
        text = text[1:]
    try:
        return Decimal(text)
    except InvalidOperation:
        raise ValueError("not a number: %r" % value)


def format_money(amount):
    """Render a Decimal as a plain 2-dp string for output files."""
    return str(Decimal(amount).quantize(Decimal("0.01")))


def percent(part, whole):
    """part/whole as a float percentage, 0.0 when whole is zero."""
    if not whole:
        return 0.0
    return 100.0 * part / whole


def clamp(value, low, high):
    """Pin `value` into [low, high]."""
    return max(low, min(high, value))

